using BrewNest.Contracts.Procurement;
using BrewNest.Modules.Procurement.Application.Services;
using BrewNest.Modules.Procurement.Domain.BusinessRules;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;
namespace BrewNest.Modules.Procurement.Endpoints;
internal static class ProcurementEndpoints
{
 public static IEndpointRouteBuilder MapProcurementEndpoints(this IEndpointRouteBuilder e){var g=e.MapGroup("/api/procurement").WithTags("Procurement").RequireAuthorization();
 g.MapGet("/references",(ProcurementService s,CancellationToken t)=>Run(s.References(t))).RequireAuthorization(ProcurementPermissions.Read);g.MapGet("/requisitions",(ProcurementService s,CancellationToken t)=>Run(s.Requisitions(t))).RequireAuthorization(ProcurementPermissions.Read);g.MapPost("/requisitions",(CreateRequisitionRequest r,HttpContext h,ProcurementService s,CancellationToken t)=>Run(s.CreateRequisition(r,ProcurementContext.From(h),t))).RequireAuthorization(ProcurementPermissions.RequisitionsManage);
 g.MapPost("/requisitions/{id:guid}/submit",(Guid id,ChangeProcurementStatusRequest r,HttpContext h,ProcurementService s,CancellationToken t)=>Run(s.ChangeRequisition(id,"submit",r,ProcurementContext.From(h),t))).RequireAuthorization(ProcurementPermissions.RequisitionsManage);
 g.MapPost("/requisitions/{id:guid}/approve",(Guid id,ChangeProcurementStatusRequest r,HttpContext h,ProcurementService s,CancellationToken t)=>Run(s.ChangeRequisition(id,"approve",r,ProcurementContext.From(h),t))).RequireAuthorization(ProcurementPermissions.RequisitionsApprove);
 g.MapPost("/requisitions/{id:guid}/reject",(Guid id,ChangeProcurementStatusRequest r,HttpContext h,ProcurementService s,CancellationToken t)=>Run(s.ChangeRequisition(id,"reject",r,ProcurementContext.From(h),t))).RequireAuthorization(ProcurementPermissions.RequisitionsApprove);
 g.MapGet("/rfqs",(ProcurementService s,CancellationToken t)=>Run(s.Rfqs(t))).RequireAuthorization(ProcurementPermissions.Read);g.MapPost("/rfqs",(CreateRfqRequest r,HttpContext h,ProcurementService s,CancellationToken t)=>Run(s.CreateRfq(r,ProcurementContext.From(h),t))).RequireAuthorization(ProcurementPermissions.SourcingManage);g.MapGet("/quotations",(Guid? rfqId,ProcurementService s,CancellationToken t)=>Run(s.Quotations(rfqId,t))).RequireAuthorization(ProcurementPermissions.Read);g.MapPost("/rfqs/{id:guid}/quotations",(Guid id,SubmitQuotationRequest r,HttpContext h,ProcurementService s,CancellationToken t)=>Run(s.SubmitQuotation(id,r,ProcurementContext.From(h),t))).RequireAuthorization(ProcurementPermissions.SourcingManage);g.MapPost("/quotations/{id:guid}/select",(Guid id,ChangeProcurementStatusRequest r,HttpContext h,ProcurementService s,CancellationToken t)=>Run(s.SelectQuotation(id,r,ProcurementContext.From(h),t))).RequireAuthorization(ProcurementPermissions.OrdersManage);
 g.MapGet("/orders",(ProcurementService s,CancellationToken t)=>Run(s.Orders(t))).RequireAuthorization(ProcurementPermissions.Read);g.MapPost("/orders/{id:guid}/approve",(Guid id,ChangeProcurementStatusRequest r,HttpContext h,ProcurementService s,CancellationToken t)=>Run(s.DecideOrder(id,true,r,ProcurementContext.From(h),t))).RequireAuthorization(ProcurementPermissions.OrdersApprove);g.MapPost("/orders/{id:guid}/reject",(Guid id,ChangeProcurementStatusRequest r,HttpContext h,ProcurementService s,CancellationToken t)=>Run(s.DecideOrder(id,false,r,ProcurementContext.From(h),t))).RequireAuthorization(ProcurementPermissions.OrdersApprove);
 g.MapGet("/receipts",(ProcurementService s,CancellationToken t)=>Run(s.Receipts(t))).RequireAuthorization(ProcurementPermissions.Read);g.MapPost("/orders/{id:guid}/receipts",(Guid id,CreateGoodsReceiptRequest r,HttpContext h,ProcurementService s,CancellationToken t)=>Run(s.CreateReceipt(id,r,ProcurementContext.From(h),t))).RequireAuthorization(ProcurementPermissions.ReceiptsManage);g.MapPost("/receipts/{id:guid}/lines/{lineId:guid}/inspection",(Guid id,Guid lineId,CompleteInspectionRequest r,HttpContext h,ProcurementService s,CancellationToken t)=>Run(s.Inspect(id,lineId,r,ProcurementContext.From(h),t))).RequireAuthorization(ProcurementPermissions.InspectionsManage);g.MapPost("/vendor-returns",(CreateVendorReturnRequest r,HttpContext h,ProcurementService s,CancellationToken t)=>Run(s.Return(r,ProcurementContext.From(h),t))).RequireAuthorization(ProcurementPermissions.ReturnsManage);g.MapGet("/status-history",(ProcurementService s,CancellationToken t)=>Run(s.History(t))).RequireAuthorization(ProcurementPermissions.Read);return e;}
 private static async Task<IResult> Run<T>(Task<ProcurementResult<T>> task){var r=await task;if(r.Succeeded)return Results.Ok(r.Value);var(code,title)=r.Status switch{ProcurementResultStatus.Validation=>(400,"Procurement validation failed"),ProcurementResultStatus.NotFound=>(404,"Procurement record not found"),ProcurementResultStatus.Conflict=>(409,"Procurement conflict"),ProcurementResultStatus.Forbidden=>(403,"Procurement approval denied"),_=>(500,"Procurement operation failed")};return Results.Problem(statusCode:code,title:title,detail:string.Join(' ',r.Errors),extensions:new Dictionary<string,object?>{{"errors",r.Errors}});}
}
